    {"text": "Рисунок 29 относится к диаграммам разных методов, включая градиент-зонд, потенциал-зонд и экранированный зонд.", "claims": ["c3", "c4"]}
  ],
  "terms_defined": [
    {"term": "подсчётный параметр", "term_en": "calculation parameter", "abbr": "", "definition": "Величина, которую используют при подсчёте запасов нефти и газа. Эффективная мощность — один из них.", "claims": ["c1"]},
    {"term": "подсчёт запасов", "term_en": "reserves estimation", "abbr": "", "definition": "Расчёт количества нефти и газа в месторождении по известным параметрам пласта.", "claims": ["c1"]},
    {"term": "кровля и подошва пласта", "term_en": "top and base of a bed", "abbr": "", "definition": "Верхняя и нижняя границы пласта. Их положение задаёт его толщину.", "claims": ["c2"]},
    {"term": "мощность пласта", "term_en": "bed thickness", "abbr": "", "definition": "Толщина пласта между его кровлей и подошвой.", "claims": ["c2"]},
    {"term": "однородный пласт", "term_en": "homogeneous bed", "abbr": "", "definition": "Пласт, в котором порода одинакова по всей толще. Это рабочее определение, в главе не сформулировано.", "claims": []},
    {"term": "диаграмма геофизического метода (каротажная диаграмма)", "term_en": "logging curve / log plot", "abbr": "", "definition": "Запись показаний прибора в скважине. По ней проводят границы пластов.", "claims": ["c2"]}
  ],
